import { useCallback } from 'react';
import { useDungeonMapQuery } from './dungeon-map-query';
import { useDungeonMovementRules } from './dungeon-movement-rules';

export function usePathfinding({ gameSession, visibilityMap = null, foundPassages = [] }) {
    const mapQuery = useDungeonMapQuery({ gameSession, visibilityMap });
    const movementRules = useDungeonMovementRules({ mapQuery, foundPassages });

    const calculatePath = useCallback((startX, startY, targetX, targetY, maxDepth, excludeEntityId) => {
        if (!movementRules.isValidDestination(targetX, targetY, excludeEntityId)) {
            return [];
        }

        const queue = [{ x: startX, y: startY, path: [] }];
        const visited = new Set();
        visited.add(`${startX},${startY}`);

        const directions = [
            { dx: 0, dy: -1 }, // Up
            { dx: 0, dy: 1 },  // Down
            { dx: -1, dy: 0 }, // Left
            { dx: 1, dy: 0 }   // Right
        ];

        while (queue.length > 0) {
            const current = queue.shift();

            if (current.x === targetX && current.y === targetY) {
                return current.path;
            }

            if (current.path.length >= maxDepth) {
                continue;
            }

            for (let i = 0; i < directions.length; i++) {
                const dir = directions[i];
                const neighborX = current.x + dir.dx;
                const neighborY = current.y + dir.dy;
                const neighborKey = `${neighborX},${neighborY}`;

                if (!visited.has(neighborKey)) {
                    if (movementRules.isWalkable(current.x, current.y, neighborX, neighborY, excludeEntityId, foundPassages)) {
                        visited.add(neighborKey);
                        queue.push({
                            x: neighborX,
                            y: neighborY,
                            path: [...current.path, { x: neighborX, y: neighborY }]
                        });
                    }
                }
            }
        }

        return [];
    }, [movementRules, foundPassages]);

    /** Tutte le celle raggiungibili entro maxDepth passi (BFS). */
    const getReachableCells = useCallback((startX, startY, maxDepth, excludeEntityId) => {
        if (maxDepth == null || maxDepth <= 0) return [];

        const directions = [
            { dx: 0, dy: -1 },
            { dx: 0, dy: 1 },
            { dx: -1, dy: 0 },
            { dx: 1, dy: 0 },
        ];
        const reachable = [];
        const queue = [{ x: startX, y: startY, depth: 0 }];
        const visited = new Set([`${startX},${startY}`]);

        while (queue.length > 0) {
            const current = queue.shift();
            if (current.depth > 0) {
                reachable.push({ x: current.x, y: current.y });
            }
            if (current.depth >= maxDepth) continue;

            for (const dir of directions) {
                const nx = current.x + dir.dx;
                const ny = current.y + dir.dy;
                const key = `${nx},${ny}`;
                if (visited.has(key)) continue;
                if (
                    !movementRules.isWalkable(
                        current.x,
                        current.y,
                        nx,
                        ny,
                        excludeEntityId,
                        foundPassages
                    )
                ) {
                    continue;
                }
                visited.add(key);
                queue.push({ x: nx, y: ny, depth: current.depth + 1 });
            }
        }

        return reachable;
    }, [movementRules, foundPassages]);

    return {
        calculatePath,
        getReachableCells,
    };
}